insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','___, ta forma odmowy może zabrzmieć zbyt bezpośrednio.','["Mam wrażenie, że","Każdy wie, że","Bez wyjątku"]',0,'Mam wrażenie, że ogranicza siłę uogólnienia.',0);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','Co dokładnie masz ___, mówiąc «normalne zachowanie»?','["na myśli","w zamiarze do","za ton"]',0,'Mieć na myśli — иметь в виду.',1);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','Jeśli zabrzmiało to jak krytyka, ___ powiedzieć, że potrzebuję więcej czasu.','["chciałem","stereotyp","odczytam"]',0,'Формула отделяет эффект от намерения.',2);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','Warto zapytać, ___ przypisać komuś intencję.','["zanim","mimo","wskutek"]',0,'Zanim обозначает действие до вывода.',3);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','Составьте: По моему опыту, лучше уточнить норму, чем делать предположения.','["W moim doświadczeniu lepiej doprecyzować normę, niż robić założenia.","Moje doświadczenie norma lepsza założeń.","Stereotyp doprecyzował niż norma."]',0,'Lepiej…, niż… сравнивает решения.',4);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-grammar','Составьте: Если я правильно понимаю, молчание не означало несогласия.','["Jeśli dobrze rozumiem, milczenie nie oznaczało sprzeciwu.","Dobrze rozumiejąc milczenie bez sprzeciwem.","Jeśli milczenie, rozumiem nie oznaczać."]',0,'Формула проверяет интерпретацию нейтрально.',5);
