insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-reading-check','Jak opisała sytuację?','["Jako własne wrażenie","Jako cechę wszystkich ludzi","Jako pewny stereotyp"]',0,'Она говорила от своего опыта.',1);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-reading-check','Dlaczego zatrzymano uogólnienie?','["Kraj nie wyjaśnia każdej osoby","Nie wolno mówić o komunikacji","Wszyscy mieli identyczny styl"]',0,'Поведение зависит от многих факторов.',2);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-reading-check','Jaką normę ustalono?','["Dodawać intencję i kolejny krok","Nie pisać wiadomości","Zawsze odpowiadać jednym słowem"]',0,'Команда добавляет контекст.',3);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-reading-check','Co zrobić z ostrym komunikatem?','["Najpierw poprosić o doprecyzowanie","Natychmiast oskarżyć autora","Przerwać współpracę"]',0,'Уточнение предшествует оценке.',4);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2intercultural-reading-check','Jaki jest wniosek?','["Różne oczekiwania można uzgodnić","Stereotyp wystarcza do wyjaśnienia","Stylu nie można zmieniać"]',0,'Команда адаптировала нормы без стирания различий.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2intercultural-spotkanie-bez-zalozen','b2-intercultural-communication','Spotkanie bez założeń','Как международная команда разобрала недоразумение без стереотипов','B2',13,'🌍','["Zespół projektowy spotkał się po trudnej wideokonferencji. Lena odebrała krótką odpowiedź kolegi jako lekceważącą, natomiast Amir był przekonany, że jedynie oszczędza czas. Zamiast przypisywać mu intencję, prowadząca poprosiła obie strony o opisanie faktów i własnej interpretacji.","Lena powiedziała: „Mam wrażenie, że moje pytanie zostało pominięte”. Nie stwierdziła, że Amir zawsze ignoruje współpracowników. Amir wyjaśnił, że w jego zespole krótka odpowiedź zwykle sygnalizuje zgodę i szybkie przejście do działania. Przyznał jednak, że w wiadomości trudno było odczytać życzliwy ton.","Rozmowa zeszła na różnice kulturowe, ale prowadząca zatrzymała zbyt szerokie uogólnienie. Przypomniała, że kraj pochodzenia nie wyjaśnia automatycznie zachowania konkretnej osoby. Ważne są także rola zawodowa, język, relacja i indywidualne przyzwyczajenia.","Uczestnicy ustalili prostą normę: przy niejasnej decyzji będą dopisywać jedno zdanie z intencją oraz terminem kolejnego kroku. Jeśli komunikat zabrzmi ostro, odbiorca najpierw poprosi o doprecyzowanie, zamiast odpowiadać podobnym tonem.","Po spotkaniu Lena i Amir uznali, że problem nie wynikał z jednej «kultury», lecz z różnych oczekiwań i ubogiego kontekstu. Wyjaśnienie nieporozumienia pozwoliło im dostosować styl bez rezygnowania z własnej tożsamości."]','{"odebrała":{"lemma":"odebrać","translation":"восприняла","part_of_speech":"глагол"},"lekceważącą":{"lemma":"lekceważący","translation":"пренебрежительной","part_of_speech":"прилагательное"},"przypisywać":{"lemma":"przypisywać","translation":"приписывать","part_of_speech":"глагол"},"pominięte":{"lemma":"pominąć","translation":"пропущено","part_of_speech":"причастие"},"sygnalizuje":{"lemma":"sygnalizować","translation":"сигнализирует","part_of_speech":"глагол"},"życzliwy":{"lemma":"życzliwy","translation":"доброжелательный","part_of_speech":"прилагательное"},"pochodzenia":{"lemma":"pochodzenie","translation":"происхождения","part_of_speech":"существительное"},"przyzwyczajenia":{"lemma":"przyzwyczajenie","translation":"привычки","part_of_speech":"существительное"},"dopisywać":{"lemma":"dopisywać","translation":"добавлять письменно","part_of_speech":"глагол"},"doprecyzowanie":{"lemma":"doprecyzowanie","translation":"уточнение","part_of_speech":"существительное"},"oczekiwań":{"lemma":"oczekiwanie","translation":"ожиданий","part_of_speech":"существительное"},"ubogiego":{"lemma":"ubogi","translation":"бедного","part_of_speech":"прилагательное"},"tożsamości":{"lemma":"tożsamość","translation":"идентичности","part_of_speech":"существительное"},"wyjaśnienie":{"lemma":"wyjaśnienie","translation":"объяснение","part_of_speech":"существительное"},"uogólnienie":{"lemma":"uogólnienie","translation":"обобщение","part_of_speech":"существительное"},"interpretacji":{"lemma":"interpretacja","translation":"интерпретации","part_of_speech":"существительное"},"intencją":{"lemma":"intencja","translation":"намерением","part_of_speech":"существительное"},"dostosować":{"lemma":"dostosować","translation":"адаптировать","part_of_speech":"глагол"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2intercultural-reading-check"}',44,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
