insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values ('b2academic-grammar','Составьте: Оба источника указывают на пользу, но используют разные методы.','["Oba źródła wskazują na korzyść, ale stosują różne metody.","Obie źródła korzyścią różne metoda.","Źródło wskazywali metody ale korzyść."]',0,'Oba согласуется с nijakim źródła.',4);
