insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2academic-dwa-badania-jeden-wniosek','b2-academic-skills','Dwa badania, jeden ostrożny wniosek','Как студентка сопоставила исследования и не преувеличила результат','B2',14,'🎓','["Natalia przygotowywała krótką analizę o nauce słownictwa. Znalazła dwa recenzowane artykuły. Pierwszy porównywał regularne powtórki z jednorazową nauką, drugi badał wpływ samodzielnego układania zdań na zapamiętywanie.","W pierwszym badaniu próba była duża, ale test trwał tylko trzy tygodnie. Dane wskazywały na przewagę regularnych powtórek. Autorzy podkreślili jednak, że krótki zakres czasowy nie pozwala stwierdzić, czy efekt utrzyma się przez rok.","Drugie badanie obejmowało mniej osób, lecz analizowało bardziej aktywne zadanie. Uczestnicy, którzy tworzyli własne przykłady, lepiej rozpoznawali słowa w nowym kontekście. Wynik sugerował korzyść, ale nie dowodził, że metoda będzie równie skuteczna na każdym poziomie.","Natalia najpierw sparafrazowała tezy, a potem dodała przypisy. Nie połączyła liczb z dwóch badań, ponieważ metody i próby były różne. Zamiast tego porównała zakres, mocne strony i ograniczenia obu projektów.","W streszczeniu napisała, że źródła łącznie wspierają regularną i aktywną pracę ze słowem. Zaznaczyła zarazem, że potrzebne są dłuższe badania. Dzięki temu wniosek był użyteczny, lecz nie udawał pewności, której dane nie dawały."]','{"recenzowane":{"lemma":"recenzowany","translation":"рецензируемые","part_of_speech":"прилагательное"},"jednorazową":{"lemma":"jednorazowy","translation":"одноразовую","part_of_speech":"прилагательное"},"wpływ":{"lemma":"wpływ","translation":"влияние","part_of_speech":"существительное"},"próba":{"lemma":"próba","translation":"выборка","part_of_speech":"существительное"},"przewagę":{"lemma":"przewaga","translation":"преимущество","part_of_speech":"существительное"},"zakres":{"lemma":"zakres","translation":"охват","part_of_speech":"существительное"},"utrzyma":{"lemma":"utrzymać się","translation":"сохранится","part_of_speech":"глагол"},"obejmowało":{"lemma":"obejmować","translation":"охватывало","part_of_speech":"глагол"},"rozpoznawali":{"lemma":"rozpoznawać","translation":"распознавали","part_of_speech":"глагол"},"dowodził":{"lemma":"dowodzić","translation":"доказывал","part_of_speech":"глагол"},"sparafrazowała":{"lemma":"sparafrazować","translation":"перефразировала","part_of_speech":"глагол"},"przypisy":{"lemma":"przypis","translation":"сноски","part_of_speech":"существительное"},"ograniczenia":{"lemma":"ograniczenie","translation":"ограничения","part_of_speech":"существительное"},"streszczeniu":{"lemma":"streszczenie","translation":"резюме","part_of_speech":"существительное"},"zarazem":{"lemma":"zarazem","translation":"одновременно","part_of_speech":"наречие"},"udawał":{"lemma":"udawać","translation":"изображал","part_of_speech":"глагол"},"pewności":{"lemma":"pewność","translation":"уверенности","part_of_speech":"существительное"},"skuteczna":{"lemma":"skuteczny","translation":"эффективная","part_of_speech":"прилагательное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2academic-reading-check"}',45,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
