insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2final-projekt-miejskiej-ciszy','b2-final-project','Projekt miejskiej ciszy','Итоговый B2-проект: данные, защита решения и честная самооценка','B2',15,'🏁','["Grupa kończąca kurs wybrała pytanie badawcze: czy jedna cicha godzina w bibliotece poprawi warunki pracy bez ograniczania dostępu innym użytkownikom? Uczestnicy ustalili dwa kryteria sukcesu: niższy poziom hałasu i brak wzrostu liczby skarg.","Wersja robocza planu zakładała obserwację przez tydzień. Po informacji zwrotnej bibliotekarki harmonogram wydłużono do miesiąca, aby porównać różne dni. Grupa mierzyła hałas, zbierała anonimowe ankiety i notowała, ile osób korzystało z przestrzeni.","Dane wskazały poprawę w strefie pracy, a liczba skarg nie wzrosła. Niemniej próba obejmowała tylko jedną filię. Zespół nie twierdził więc, że rozwiązanie automatycznie sprawdzi się w każdej bibliotece. To zastrzeżenie znalazło się na slajdzie z głównym wnioskiem.","Podczas obrony komisja przedstawiła kontrargument: cisza mogła wynikać z mniejszego ruchu w badanym miesiącu. Prelegentka przyznała, że to możliwe, po czym odwołała się do dziennych danych o frekwencji. Zaproponowała też powtórzenie pomiaru jesienią.","W samoocenie grupa uznała projekt za udany według przyjętych kryteriów, lecz wskazała dalszy krok. Gdyby zaczynali ponownie, wcześniej skonsultowaliby ankietę i objęliby badaniem drugą filię. Obrona stanowiska nie polegała na ukrywaniu słabości, tylko na pokazaniu, co dane pozwalają stwierdzić."]','{"kończąca":{"lemma":"kończyć","translation":"завершающая","part_of_speech":"причастие"},"ograniczania":{"lemma":"ograniczanie","translation":"ограничения","part_of_speech":"существительное"},"skarg":{"lemma":"skarga","translation":"жалоб","part_of_speech":"существительное"},"zakładała":{"lemma":"zakładać","translation":"предполагала","part_of_speech":"глагол"},"anonimowe":{"lemma":"anonimowy","translation":"анонимные","part_of_speech":"прилагательное"},"przestrzeni":{"lemma":"przestrzeń","translation":"пространства","part_of_speech":"существительное"},"filia":{"lemma":"filia","translation":"филиал","part_of_speech":"существительное"},"zastrzeżenie":{"lemma":"zastrzeżenie","translation":"оговорка","part_of_speech":"существительное"},"komisja":{"lemma":"komisja","translation":"комиссия","part_of_speech":"существительное"},"wynikać":{"lemma":"wynikać","translation":"следовать","part_of_speech":"глагол"},"frekwencji":{"lemma":"frekwencja","translation":"посещаемости","part_of_speech":"существительное"},"pomiaru":{"lemma":"pomiar","translation":"измерения","part_of_speech":"существительное"},"samoocenie":{"lemma":"samoocena","translation":"самооценке","part_of_speech":"существительное"},"przyjętych":{"lemma":"przyjąć","translation":"принятых","part_of_speech":"причастие"},"skonsultowaliby":{"lemma":"skonsultować","translation":"проконсультировали бы","part_of_speech":"глагол"},"objęliby":{"lemma":"objąć","translation":"охватили бы","part_of_speech":"глагол"},"ukrywaniu":{"lemma":"ukrywanie","translation":"сокрытии","part_of_speech":"существительное"},"słabości":{"lemma":"słabość","translation":"слабости","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2final-reading-check"}',46,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
